import { SelectItem } from 'primeng/primeng';
import { Component, OnInit, ElementRef, ViewChild } from '@angular/core';
import { Router } from '@angular/router';
import { DatePipe } from '@angular/common';

import { MessageService } from 'primeng/components/common/messageservice';
import { FuncionService } from './../../service/funcion.service';
import { PermisoService } from './../../service/permiso.service';
import { Global } from '../../global';

@Component({
    selector: 'app-permisos-listado',
    templateUrl: './listado.component.html'
})
export class PermisosListadoComponent implements OnInit {
    loading: boolean;
    displayDialogDelete: boolean;
    displayDialogCreate: boolean;
    params;
    permiso: any = {funcion: {}};
    permisos = [];
    filteredCC = [];
    funcionOptions: SelectItem[] = [];

    constructor(
        private router: Router,
        private datepipe: DatePipe,
        private messageService: MessageService,
        private global: Global,
        private funcionService: FuncionService,
        private permisoService: PermisoService) { }

    ngOnInit(): void {
        this.params = {};
        this.loadTable();
        this.setCombos();
    }
    setCombos() {
        this.funcionService.getAll().then(funciones => this.setSelectOptions(funciones, this.funcionOptions, 'descripcion', 'id'));
    }

    setSelectOptions(array, select, label, value) {
        array.forEach(element => {
            select.push({ label: element[label], value: element[value] });
        });
    }

    loadTable(event?) {
        if (event) {
            this.params = event;
            this.params.filters = null;
        }

        Object.keys(this.params).forEach(key => !this.params[key] && delete this.params[key]);

        setTimeout(() => {
            this.loading = true;
            this.permisoService.getFiltered(this.params).then(resp => {
                this.permisos = resp;
                this.loading = false;
            })
            .catch(error => {
                this.handleError(error);
                this.loading = false;
            });
        });
    }

    showDelete(permiso) {
        this.permiso = permiso;
        this.displayDialogDelete = true;
    }

    delete() {
        this.loading = true;
        this.permisoService.delete(this.permiso).then(id => {
            this.messageService.add({
                severity: 'success',
                detail: 'Borrado exitoso'
            });
            this.displayDialogDelete = false;
            this.loadTable();
        }).catch(error => this.handleError(error));
    }

    showCreate() {
        this.permiso = {funcion: {}};
        this.displayDialogCreate = true;
    }

    create() {
        console.log(this.permiso.funcion);
        if (!this.permiso.codPuesto)
            this.messageService.add({severity: 'error', detail: 'Debe informar el puesto'});
        else if (!this.permiso.codArea)
            this.messageService.add({severity: 'error', detail: 'Debe informar el &aacute;rea'});
        else if (!this.permiso.funcion.id)
            this.messageService.add({severity: 'error', detail: 'Debe seleccionar una funci&oacute;n'});
        else {
            this.permisoService.create(this.permiso).then(id => {
                this.messageService.add({severity: 'success', detail: 'Alta exitosa'});
                this.displayDialogCreate = false;
                this.loadTable();
            })
            .catch(error => this.handleError(error));
        }
    }

    handleError(error) {
        console.log(error);
        this.loading = false;
        if (error.id == 1)
            this.messageService.add({severity: 'error', detail: error.status});
        else if (error.id == 403)
            this.messageService.add({severity: 'error', detail: 'No tiene permisos para realizar la acci&oacute;n'});
        else
            this.messageService.add({severity: 'error', detail: 'Se ha producido un error'});
    }
}



