import { Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';

import 'rxjs/add/operator/toPromise';

import { HttpHeaders } from '@angular/common/http';

@Injectable()
export class PermisoService {
    private serviceUrl = 'api/permiso';
    private headers = new HttpHeaders({ 'Content-Type': 'application/json' });
    constructor(private http: HttpClient) { }

    getFiltered(paramsIn): Promise<any> {
        let params = new URLSearchParams();
        for (let key in paramsIn) {
            params.set(key, paramsIn[key]);
        }

        return this.http.get(this.serviceUrl + '?' + params.toString())
            .toPromise()
            .catch(this.handleError);
    }

    delete(permiso): Promise<any> {
        const url = this.serviceUrl + '/delete';
        return this.http.post(url, permiso)
            .toPromise()
            .catch(this.handleError);
    }

    create(permiso): Promise<any> {
        return this.http
            .post(this.serviceUrl, permiso, { headers: this.headers })
            .toPromise()
            .catch(this.handleError);
    }

    private handleError(error: any): Promise<any> {
        return Promise.reject(error.error || error.message || error);
    }
}



