import { SelectItem } from 'primeng/primeng';
import { Component, OnInit, ElementRef, ViewChild } from '@angular/core';
import { Router } from '@angular/router';
import { DatePipe } from '@angular/common';

import { MessageService } from 'primeng/components/common/messageservice';
import { JustificacionService } from './../../service/justificacion.service';

import { Global } from '../../global';

@Component({
    selector: 'app-justificacion-listado',
    templateUrl: './listado.component.html'
})
export class JustificacionListadoComponent implements OnInit {
    loading: boolean;
    displayDialogDelete: boolean;
    displayDialogCreate: boolean;
    displayDialogEdit: boolean;
    params;
    searchedParams;
    justificacionesForDelete;
    justificacionesTab = [];
    justificacionesForEdit;
    justificacionesOptions: SelectItem[] = [];

    constructor(
        private router: Router,
        private datepipe: DatePipe,
        private messageService: MessageService,
        private global: Global,
        private justificacionesService: JustificacionService) { }

    ngOnInit(): void {
        this.params = {};
        this.setFilterJustificacion();
    }
    setFilterJustificacion() {
        this.justificacionesOptions = [];
        this.justificacionesService.getAll().then(resp => {
            this.justificacionesTab = resp;
            resp.forEach(element => this.justificacionesOptions.push({ label: element['descripcion'], value: element['id'] }));
        }).catch(error => this.handleError(error));
    }
    loadTable(event?) {
        if (event) {
            this.params = event;
            this.params.filters = null;
        }

        Object.keys(this.params).forEach(key => !this.params[key] && delete this.params[key]);
        this.searchedParams = JSON.parse(JSON.stringify(this.params));
        setTimeout(() => {
            this.loading = true;
            this.justificacionesService.getFiltered(this.params).then(resp => {
                this.justificacionesTab = resp;
                this.loading = false;
            })
            .catch(error => { this.handleError(error);
            this.loading = false;
            });
        });
        }

    showDeleteJustificaciones(justificaciones) {
        this.justificacionesForDelete = justificaciones;
        this.displayDialogDelete = true;
    }
    deleteJustificaciones() {
        this.loading = true;
        this.justificacionesService.delete(this.justificacionesForDelete).then(id => {
            this.messageService.add({
                severity: 'success',
                detail: 'Justificaciones borrado con \u00e9xito'
            });
            this.displayDialogDelete = false;
            this.loadTable();
            this.setFilterJustificacion();
            // this.onSubmit.emit(id);
            // this.visibleChange.emit(false);
        }).catch(error => this.handleError(error));
    }
    showEditJustificaciones(justificaciones) {
        this.justificacionesForEdit = {
            id: justificaciones.id,
            descripcion: justificaciones.descripcion
        };
        this.displayDialogEdit = true;
    }
    editJustificaciones() {
        if (!this.justificacionesForEdit['descripcion'] || this.justificacionesForEdit['descripcion'].trim() === '') {
            this.messageService.add({
                severity: 'error',
                detail: 'Debe ingresar los datos'
            });
        } else {
        this.loading = true;
        this.justificacionesService.edit(this.justificacionesForEdit).then(id => {
            this.messageService.add({
                severity: 'success',
                detail: 'Justificaciones editado con \u00e9xito'
            });
            this.loadTable();
            this.setFilterJustificacion();
            this.displayDialogEdit = false;
            // this.onSubmit.emit(id);
            // this.visibleChange.emit(false);
        }).catch(error => this.handleError(error));
        }
    }
    showCreate() {
        setTimeout(() => {
            if (this.params['newDesc']) delete this.params['newDesc'];
        });
        this.displayDialogCreate = true;
    }
    confirmJustificaciones() {
        if (!this.params['newDesc'] || this.params['newDesc'].trim() === '' ) {
            this.messageService.add({
                severity: 'error',
                detail: 'Debe ingresar los datos'
            });
        } else {
        let justificaciones = {
            id: null,
            descripcion: this.params['newDesc']
          };
          this.justificacionesService.create(justificaciones).then(id => {
                this.messageService.add({
                    severity: 'success',
                    detail: 'Alta exitosa'
                });
                this.loadTable();
                this.setFilterJustificacion();
                this.displayDialogCreate = false;
                delete this.params['newDesc'];
            }
          ).catch(error => this.handleError(error));
        }
    }
    handleError(error) {
        console.log(error);
        this.loading = false;
        if (error.id == 403)
            this.messageService.add({severity: 'error', detail: 'No tiene permisos para realizar la acci&oacute;n'});
        else
            this.messageService.add({severity: 'error', detail: 'Se ha producido un error'});
    }
    clearFilters() {
        this.params = {};
    }
    exportXLS() {
        let params = new URLSearchParams();
        for (let key in this.searchedParams) {
            params.set(key, this.searchedParams[key]);
        }
            window.open('api/justificacion/exportXLS?' + params.toString() , '_self');
    }
}



