import { SelectItem } from 'primeng/primeng';
import { Component, OnInit, ElementRef, ViewChild } from '@angular/core';
import { Router } from '@angular/router';
import { DatePipe } from '@angular/common';

import { MessageService } from 'primeng/components/common/messageservice';
import { PedidoService } from './../../service/pedido.service';
import { MaterialService } from './../../service/material.service';
import { CentroCostosService } from './../../service/centrocostos.service';
import { EstadoService } from './../../service/estado.service';
import { PrioridadService } from './../../service/prioridad.service';
import { Global } from '../../global';
import { JustificacionService } from './../../service/justificacion.service';
import { isNullOrUndefined } from 'util';

@Component({
    selector: 'app-pedido-listado',
    templateUrl: './listado.component.html'
})
export class PedidoListadoComponent implements OnInit {
    loading: boolean;
    displayDialogDelete: boolean;
    displayDialogEdit: boolean;
    displayDialogJustif: boolean;
    checkRejected: String = 'false';
    checkRejectedAux: String = 'false';
    params;
    pedido = [];
    pedidoForDelete;
    pedidoForEdit;
    selectedPedido = [];
    recepcion = [];
    resuelto = [];
    pedidosDistintos = [];
    materialOptions: SelectItem[] = [];
    centroCostosOptions: SelectItem[] = [];
    estadoOptions: SelectItem[] = [];
    prioridadOptions: SelectItem[] = [];
    today = new Date();
    justificacionesOptions: SelectItem[] = [];
    pedidosExcedidos = [];
    displayDialog: boolean;

    constructor(
        private router: Router,
        private datepipe: DatePipe,
        private messageService: MessageService,
        private global: Global,
        private pedidoService: PedidoService,
        private materialService: MaterialService,
        private centroCostosService: CentroCostosService,
        private estadoService: EstadoService,
        private prioridadService: PrioridadService,
        private justificacionService: JustificacionService) { }

    ngOnInit(): void {

        this.params = {};
        this.loadTable();
        this.setCombos();
    }
    setCombos() {
        this.materialService.getAll().then(materiales => this.setSelectOptions(materiales, this.materialOptions, 'descripcion', 'id'));
                // materiales.forEach(material => {
                //     this.materialOptions.push({ label: material['tipo_material']['descripcion'], value: material['id']});
                // }));
        this.centroCostosService.getByUser().then(centroCostos => this.setSelectOptions(centroCostos, this.centroCostosOptions, 'descripcion', 'id'));
        this.estadoService.getAll().then(estados => this.setSelectOptions(estados, this.estadoOptions, 'descripcion', 'id'));
        this.prioridadService.getAll().then(prioridad => this.setSelectOptions(prioridad, this.prioridadOptions, 'descripcion', 'id'));
        this.justificacionService.getAll().then(justificacion => this.setSelectOptions(justificacion, this.justificacionesOptions, 'descripcion', 'id'));
    }

    setSelectOptions(array, select, label, value) {
        array.forEach(element => {
            select.push({ label: element[label], value: element[value] });
        });
    }
    loadTable(event?) {
        if (event) {
            this.params = event;
            this.params.filters = null;
        }

        Object.keys(this.params).forEach(key => !this.params[key] && delete this.params[key]);

        setTimeout(() => {
            this.loading = true;
            this.loadPendientes();
            this.loadTratados();
            this.loadResueltos();


        });
    }
    buscarTratadoRecepcion() {
        Object.keys(this.params).forEach(key => !this.params[key] && delete this.params[key]);
        setTimeout(() => {
            this.loading = true;
            this.pedidoService.getTratado(this.params).then(resp => {
                this.recepcion = resp.recepcion;
                this.loading = false;
            })
                .catch(error => {
                    console.log(error);
                    this.loading = false;
                    this.messageService.add({ severity: 'error', detail: 'Error al obtener lista Tratado/Recepcion' });
                });
        });
    }
    viewPedido(pedido) {
        this.router.navigate(['/pedido', pedido.id]);
    }
    buscarPendientes() {
        Object.keys(this.params).forEach(key => !this.params[key] && delete this.params[key]);
        setTimeout(() => {
            this.pedidoService.getPendiente(this.params).then(resp => {
                this.pedido = resp.pendiente;
                this.loading = false;
            })
                .catch(error => {
                    console.log(error);
                    this.loading = false;
                    this.messageService.add({ severity: 'error', detail: 'Error al obtener lista de pedidos pendientes' });
                });
        });
    }
    loadPendientes() {
        Object.keys(this.params).forEach(key => !this.params[key] && delete this.params[key]);
        this.pedidoService.getPendiente(this.params).then(resp => {
            this.pedido = resp.pendiente;
            this.loading = false;
        })
            .catch(error => {
                console.log(error);
                this.loading = false;
                this.messageService.add({ severity: 'error', detail: 'Error al obtener lista de pedidos pendientes' });
            });
    }
    loadTratados() {
        Object.keys(this.params).forEach(key => !this.params[key] && delete this.params[key]);
        this.pedidoService.getTratado(this.params).then(resp => {
            this.recepcion = resp.recepcion;
            this.loading = false;
        })
            .catch(error => {
                console.log(error);
                this.loading = false;
                this.messageService.add({ severity: 'error', detail: 'Error al obtener lista Tratado/Recepcion' });
            });
    }
    buscarResueltos() {
        setTimeout(() => {
        this.loadResueltos();
        });
    }
    loadResueltos() {
        Object.keys(this.params).forEach(key => !this.params[key] && delete this.params[key]);
        this.params['checkRejected'] = this.checkRejected;
        this.checkRejectedAux = this.checkRejected;
        this.pedidoService.getResuelto(this.params).then(resp => {
            this.resuelto = resp.resuelto;
            this.loading = false;
        })
            .catch(error => {
                console.log(error);
                this.loading = false;
                this.messageService.add({ severity: 'error', detail: 'Error al obtener lista de pedidos resueltos' });
            });
    }
    showDeletePedido(pedido) {
        //console.log(pedido);
        this.pedidoForDelete = pedido;
        this.displayDialogDelete = true;
    }
    deletePedido() {
        //console.log(this.pedidoForDelete);
        this.loading = true;
        this.pedidoService.delete(this.pedidoForDelete.id).then(id => {
            this.messageService.add({
                severity: 'success',
                detail: 'Pedido borrado con \u00e9xito'
            });
            this.displayDialogDelete = false;
            this.loadPendientes();
            // this.onSubmit.emit(id);
            // this.visibleChange.emit(false);
        }).catch(error => this.handleError(error));
    }
    showEditPedido(pedido) {
        //console.log(pedido);
        this.pedidoForEdit = {
            id: pedido.id,
            ccostos: pedido.ccostos,
            prioridad: pedido.prioridad,
            fe_solicitud: pedido.fe_solicitud,
            fe_recepcion: pedido.fe_recepcion,
            fe_entrega: pedido.fe_entrega,
            cod_usuario_recepcion: pedido.cod_usuario_recepcion,
            validacion: pedido.validacion,
            estado: pedido.estado,
            cantidad: pedido.cantidad,
            cant_aprobada: pedido.cant_aprobada,
            cantidad_recepcion: pedido.cantidad_recepcion,
            material: pedido.material,
            observaciones: [{id_pedido: pedido.id,
                             operacion: 'JUSTIFICACION'}]
        };
       // console.log(this.pedidoForEdit);
        this.displayDialogEdit = true;
    }
    editPedido() {
        this.loading = true;
        if (this.pedidoForEdit.cantidad > this.pedidoForEdit.material.cantidad_media) {
            let id = null;
            if ( this.pedidoForEdit.id != null)
              id =  this.pedidoForEdit.id;
            let pedido = {
              id: id,
              prioridad: { id:  this.pedidoForEdit.prioridad },
              cantidad:  this.pedidoForEdit.cantidad,
              material:  this.pedidoForEdit.material,
              observaciones: [{id_pedido: this.pedidoForEdit.id,
                               operacion: 'JUSTIFICACION'}]
            };
            if ( this.pedidosExcedidos.length > 0)
                console.log('Ya posee justificación');
            else {
                this.pedidosExcedidos.push(pedido);
            }
            this.displayDialog = true;
        }
        if (!this.displayDialog) {
            this.confirmPedido();
    }
}

confirmPedido() {
             this.displayDialog = false;
            this.pedidoService.edit(this.pedidoForEdit).then(id => {
            this.messageService.add({
                severity: 'success',
                detail: 'Pedido editado con \u00e9xito'
            });
            this.loadPendientes();
            this.displayDialogEdit = false;
            // this.onSubmit.emit(id);
            // this.visibleChange.emit(false);
        }).catch(error => this.handleError(error));
    }
    cancelDialog() {
        this.pedidosExcedidos = [];
        this.displayDialog = false;
    }

    recibir() {
        var validacion = "";
        this.selectedPedido.forEach(element => {
            if(element.fe_tratamiento == null){
            validacion = "No se puede marcar como recibido pedidos que a\u00FAn no fueron tratados, desmarque los pedidos con Fecha Tratamiento vac\u00CDa"
            }
           
          });
          if (validacion =="") {
            this.selectedPedido.forEach(element => {
                if ( element.cant_aprobada !== element.cantidad_recepcion) {
                  let id = null;
                  if (element.id != null)
                    id = element.id;
                  let pedido = {
                    id: id,
                    prioridad: element.prioridad,
                    estado: element.estado,
                    cantidad: element.cantidad,
                    cant_aprobada: element.cant_aprobada,
                    cantidad_recepcion: element.cantidad_recepcion,
                    material: element.material,
                    observaciones: [{operacion: 'RECEPCION'}].concat(element.observaciones)
                  };
                 // console.log(pedido);
                  this.pedidosDistintos.push(pedido);
                  this.displayDialogJustif = true;
                }
              });
              if (!this.displayDialogJustif) {
                this.confirmRecibir();
              }
          } else {
            this.messageService.add({
                severity: 'error',
                detail: validacion
            });
              
          }

        }

    confirmRecibir() {
        let pedidos = this.selectedPedido.filter( p => p.cant_aprobada === p.cantidad_recepcion);
        if (this.pedidosDistintos.length > 0) {
            pedidos = pedidos.concat(this.pedidosDistintos);
        }
        this.displayDialogJustif = false;
        this.loading = true;
        this.pedidoService.recibir(pedidos).then(id => {
            this.messageService.add({
                severity: 'success',
                detail: 'Pedidos recibidos con \u00e9xito'
            });
            this.loadTratados();
            this.loadResueltos();
            this.selectedPedido = [];
            this.pedidosDistintos = [];
            // this.onSubmit.emit(id);
            // this.visibleChange.emit(false);
        }).catch(error => this.handleError(error));
    }

    handleError(error) {
        console.log(error);
        this.messageService.add({
            severity: 'error',
            detail: 'Se ha producido un error'
        });
    }

    rowOnlyNumbers(fc) {
        //console.log(fc);
        fc = (String(fc).replace(/[^0-9]+/g, ''));
        return fc;
    }
    clearFilters() {
        this.params = {};
    }
    exists(data, arg?: String) {
        let obs;
        if (isNullOrUndefined(arg)) {
            if (this.checkRejectedAux === 'false') arg = 'RECEPCION';
            else arg = 'RECHAZO';
        }
        obs = data.observaciones.find(e => e.operacion === arg);
        if (obs !== undefined && obs.id_justificacion) {
            // reordeno el array para que la que yo busco aparezca en la pos [0]
            data.observaciones = [obs].concat(data.observaciones.filter(e => e.operacion !== arg));
            return true;
        }
        return false;
    }
}



