import { Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';

import 'rxjs/add/operator/toPromise';

import { HttpHeaders } from '@angular/common/http';

@Injectable()
export class JustificacionService {
    private justificacionesUrl = 'api/justificacion';
    private headers = new HttpHeaders({ 'Content-Type': 'application/json' });
    constructor(private http: HttpClient) { }

    getAll(): Promise<any[]> {
        return this.http.get(this.justificacionesUrl, { headers: this.headers })
            .toPromise()
            .catch(this.handleError);
    }
    getFiltered(paramsIn): Promise<any> {
        const filterUrl = this.justificacionesUrl + '/filtered?';
        let params = new URLSearchParams();
        for (let key in paramsIn) {
            params.set(key, paramsIn[key]);
        }

        return this.http.get(filterUrl + params.toString())
            .toPromise()
            .catch(this.handleError);
    }
    edit(justificaciones): Promise<any> {
        const url = this.justificacionesUrl + '/update';
        return this.http.post(url, justificaciones)
            .toPromise()
            .catch(this.handleError);
    }
    delete(justificaciones): Promise<any> {
        const url = this.justificacionesUrl + '/delete';
        return this.http.post(url, justificaciones)
            .toPromise()
            .catch(this.handleError);
    }
    create(justificaciones): Promise<any> {
        return this.http
            .post(this.justificacionesUrl, justificaciones, { headers: this.headers })
            .toPromise()
            .then((resp: any) => resp.id)
            .catch(this.handleError);
    }

    private handleError(error: any): Promise<any> {
        return Promise.reject(error.error || error.message || error);
    }
}



