import { Injectable } from '@angular/core';
import { HttpClient, HttpHeaders } from '@angular/common/http';

import 'rxjs/add/operator/toPromise';

@Injectable()
export class AlertaService {
    private alertaUrl = 'api/alerta';
    private headers = new HttpHeaders({ 'Content-Type': 'application/json' });

    constructor(private http: HttpClient) { }

    getAll(paramsIn): Promise<any> {
        let params = new URLSearchParams();
        for (let key in paramsIn) {
            params.set(key, paramsIn[key]);
        }

        return this.http.get(this.alertaUrl + '?' + params.toString())
            .toPromise()
            .catch(this.handleError);
    }

    create(alerta): Promise<any> {
        return this.http
            .post(this.alertaUrl, alerta, { headers: this.headers })
            .toPromise()
            .then((resp: any) => resp.id)
            .catch(this.handleError);
    }

    update(alerta): Promise<any> {
        const url = this.alertaUrl + '/update';
        return this.http.post(url, alerta, { headers: this.headers })
            .toPromise()
            .catch(this.handleError);
    }

    delete(id): Promise<any> {
        return this.http
            .delete(`${this.alertaUrl}/${id}`)
            .toPromise()
            .catch(this.handleError);
    }

    private handleError(error: any): Promise<any> {
        console.log(error);
        return Promise.reject(error);
    }
}



