import { SelectItem } from 'primeng/primeng';
import { Component, OnInit, Input, EventEmitter, Output } from '@angular/core';
import { FormGroup, FormControl, Validators, FormBuilder, FormArray } from '@angular/forms';
import { MessageService } from 'primeng/components/common/messageservice';
import { Global } from '../../global';

import { AlertaService } from './../../service/alerta.service';

@Component({
    selector: 'app-alerta-detalle',
    templateUrl: './alerta.detalle.component.html'
})
export class AlertaDetalleComponent implements OnInit {
    @Input() visible: boolean;
    @Input() alerta;
    @Input() materiales = [];
    @Input() centrosCosto = [];
    @Input() tipoAlertas = [];
    @Input() tipoAlertaOptions: SelectItem[] = [];
    @Output() visibleChange = new EventEmitter();
    @Output() onSubmit = new EventEmitter();

    form: FormGroup;
    submitted: boolean;
    centroCostosOptions: SelectItem[] = [];
    materialOptions: SelectItem[] = [];
    materialesFiltered = [];
    centrosCostoOptionsFiltered = [];
    duplicated = false;
    alertaPeriodo;

    get material(): FormControl { return this.form.get('material') as FormControl; }
    get centroCostos(): FormControl { return this.form.get('centroCostos') as FormControl; }
    get tipo(): FormControl { return this.form.get('tipo') as FormControl; }
    get valor(): FormControl { return this.form.get('valor') as FormControl; }

    constructor(
        private fb: FormBuilder,
        private global: Global,
        private messageService: MessageService,
        private alertaService: AlertaService) { }

    ngOnInit() {
        this.setForm();
    }

    setSelectOptions(array, select, label, value, showValue) {
        array.forEach(element => {
            select.push({ label: showValue ? element[value] + ' - ' + element[label] : element[label], value: element[value] });
        });
    }

    show() {
        this.duplicated = false;
        this.materialOptions = [];
        this.centroCostosOptions = [];
        this.setSelectOptions(this.materiales, this.materialOptions, 'descripcion', 'id', false);
        this.setSelectOptions(this.centrosCosto, this.centroCostosOptions, 'descripcion', 'id', true);

        if (this.alerta)
            this.alertaToForm();
        else {
            this.material.enable();
            this.centroCostos.enable();
            this.tipo.enable();
        }
    }

    setForm() {
        this.form = this.fb.group({
            material: new FormControl('', Validators.required),
            centroCostos: new FormControl('', Validators.required),
            tipo: new FormControl('', Validators.required),
            valor: new FormControl(null, [Validators.required, Validators.min(0.01)])
        });

        this.subscribeAlerta();
    }

    subscribeAlerta() {
        this.tipo.valueChanges.subscribe(val => {
            if (val)
                this.alertaPeriodo = this.tipoAlertas.find(ta =>
                    ta.tipoAlerta.id === +val.substring(0, val.indexOf('_')) &&
                    ta.periodo.id === +val.substring(val.indexOf('_') + 1));
        });
    }

    close() {
        this.form.reset();
        this.visibleChange.emit(false);
    }

    submit() {
        this.submitted = true;
        this.global.markAsDirty(this.form);

        this.validateAlerta();

        if (this.form.valid) {
            let alerta: any = this.formToAlerta();
            if (this.alerta) {
                this.alertaService.update(alerta)
                    .then(() => {
                        this.messageService.add({ severity: 'success', detail: 'Alerta modificada con \u00e9xito' });
                        this.onSubmit.emit(alerta.id);
                        this.visibleChange.emit(false);
                    })
                    .catch(error => this.handleError(error));
            } else {
                this.alertaService.create(alerta)
                    .then((id) => {
                        this.messageService.add({ severity: 'success', detail: 'Alerta creada con \u00e9xito' });
                        this.onSubmit.emit(id);
                        this.visibleChange.emit(false);
                    })
                    .catch(error => this.handleError(error));
            }

        }
    }

    validateAlerta() {
        if (!this.valor.value)
            this.valor.setErrors({ 'required': true });
    }

    handleError(error) {
        console.log(error);
        if (error.error.status === 'DUPLICATED_ID') {
            this.duplicated = true;
            this.material.setErrors({ 'duplicated': true });
            this.centroCostos.setErrors({ 'duplicated': true });
            this.tipo.setErrors({ 'duplicated': true });
        } else if (error.error.status === 'PERIOD_MIN')
            this.valor.setErrors({ 'minPeriod': true });
        else if (error.error.status === 'PERIOD_MAX')
            this.valor.setErrors({ 'maxPeriod': true });
        else
            this.messageService.add({ severity: 'error', detail: 'Se ha producido un error' });
    }

    formToAlerta() {
        return {
            id: this.alerta ? this.alerta.id : null,
            material: { id: this.material.value },
            centroCostos: { id: this.centroCostos.value },
            tipoAlerta: this.alertaPeriodo.tipoAlerta,
            periodo: this.alertaPeriodo.periodo,
            valor: this.valor.value
        };
    }

    alertaToForm() {
        setTimeout(() => {
            this.form.patchValue({
                material: this.alerta.material.id,
                centroCostos: this.alerta.centroCostos.id,
                tipo: this.alerta.tipoAlerta.id + '_' + this.alerta.periodo.id,
                valor: this.alerta.valor
            });
        });

        this.material.disable();
        this.centroCostos.disable();
        this.tipo.disable();
    }

    clearErrorCombos() {
        if (this.duplicated) {
            this.material.setErrors(null);
            this.centroCostos.setErrors(null);
            this.tipo.setErrors(null);
        }
    }
}



