import { SelectItem } from 'primeng/primeng';
import { Component, OnInit, ElementRef, ViewChild } from '@angular/core';
import { Router } from '@angular/router';
import { DatePipe } from '@angular/common';

import { MessageService } from 'primeng/components/common/messageservice';
import { RubroService } from './../../service/rubro.service';

import { Global } from '../../global';

@Component({
    selector: 'app-rubro-listado',
    templateUrl: './listado.component.html'
})
export class RubroListadoComponent implements OnInit {
    loading: boolean;
    displayDialogDelete: boolean;
    displayDialogCreate: boolean;
    displayDialogEdit: boolean;
    params;
    searchedParams;
    rubroForDelete;
    rubros = [];
    rubroForEdit;
    rubrosOptions: SelectItem[] = [];

    constructor(
        private router: Router,
        private datepipe: DatePipe,
        private messageService: MessageService,
        private global: Global,
        private rubroService: RubroService) { }

    ngOnInit(): void {
        this.params = {};
        this.setFilterRubro();
    }
    setFilterRubro() {
        this.rubrosOptions = [];
        this.rubroService.getAll().then(resp => {
            this.rubros = resp;
            resp.forEach(element => this.rubrosOptions.push({ label: element['descripcion'], value: element['id'] }));
        }).catch(error => this.handleError(error));
    }
    loadTable(event?) {
        if (event) {
            this.params = event;
            this.params.filters = null;
        }

        Object.keys(this.params).forEach(key => !this.params[key] && delete this.params[key]);
            this.searchedParams = JSON.parse(JSON.stringify(this.params));
        setTimeout(() => {
            this.loading = true;
            this.rubroService.getFiltered(this.params).then(resp => {
                this.rubros = resp;
                this.loading = false;
            })
            .catch(error => { this.handleError(error);
            this.loading = false;
            });
        });
        }

    showDeleteRubro(rubro) {
        this.rubroForDelete = rubro;
        this.displayDialogDelete = true;
    }
    deleteRubro() {
        this.loading = true;
        this.rubroService.delete(this.rubroForDelete).then(resp => {
            if (resp.id === 3) {
                this.messageService.add({
                    severity: 'error',
                    detail: 'Rubro con material activo, no es posible dar la baja.'
                });
            } else {
            this.messageService.add({
                severity: 'success',
                detail: 'Rubro borrado con \u00e9xito'
            });
            }
            this.displayDialogDelete = false;
            this.loadTable();
            this.setFilterRubro();
            // this.onSubmit.emit(id);
            // this.visibleChange.emit(false);
        }).catch(error => this.handleError(error));
    }
    showEditRubro(rubro) {
        this.rubroForEdit = {
            id: rubro.id,
            descripcion: rubro.descripcion,
            nro_interfaz: rubro.nro_interfaz,
            nro_sec_tratamiento: rubro.nro_sec_tratamiento
        };
        this.displayDialogEdit = true;
    }
    editRubro() {
        if (!this.rubroForEdit['descripcion'] || this.rubroForEdit['descripcion'].trim() === '' ||
                     !this.rubroForEdit['nro_interfaz']) {
            this.messageService.add({
                severity: 'error',
                detail: 'Debe ingresar Todos los datos'
            });
        }else {
        this.loading = true;
        this.rubroService.edit(this.rubroForEdit).then(id => {
            this.messageService.add({
                severity: 'success',
                detail: 'Rubro editado con \u00e9xito'
            });
            this.loadTable();
            this.setFilterRubro();
            this.displayDialogEdit = false;
            // this.onSubmit.emit(id);
            // this.visibleChange.emit(false);
        }).catch(error => this.handleError(error));
    }
    }
    showCreate() {
        setTimeout(() => {
            if (this.params['newDesc']) delete this.params['newDesc'];
            if (this.params['newInt']) delete this.params['newInt'];
        });
        this.displayDialogCreate = true;
    }
    confirmRubro() {
        if (!this.params['newDesc'] || this.params['newDesc'].trim() === '' || !this.params['newInt'] ) {
            this.messageService.add({
                severity: 'error',
                detail: 'Debe ingresar todos los datos.'
            });
        } else {
        let rubro = {
            id: null,
            descripcion: this.params['newDesc'],
            nro_interfaz: this.params['newInt']
          };
          this.rubroService.create(rubro).then(id => {
                this.messageService.add({
                    severity: 'success',
                    detail: 'Alta exitosa'
                });
                this.loadTable();
                this.setFilterRubro();
                this.displayDialogCreate = false;
                delete this.params['newDesc'];
                delete this.params['newInt'];
            }
          ).catch(error => this.handleError(error));
        }
    }
    handleError(error) {
        console.log(error);
        this.loading = false;
        if (error.id == 403)
            this.messageService.add({severity: 'error', detail: 'No tiene permisos para realizar la acci&oacute;n'});
        else
            this.messageService.add({severity: 'error', detail: 'Se ha producido un error'});
    }
    clearFilters() {
        this.params = {};
    }
    exportXLS() {
        let params = new URLSearchParams();
        for (let key in this.searchedParams) {
            params.set(key, this.searchedParams[key]);
        }
            window.open('api/rubro/exportXLS?' + params.toString() , '_self');
    }
}



