import { Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';

import 'rxjs/add/operator/toPromise';

import { HttpHeaders } from '@angular/common/http';

@Injectable()
export class MaterialService {
    private materialUrl = 'api/material';
    private headers = new HttpHeaders({ 'Content-Type': 'application/json' });
    constructor(private http: HttpClient) { }


    getAll(): Promise<any[]> {
        return this.http.get(this.materialUrl)
            .toPromise()
            .catch(this.handleError);
    }

    get(id: string): Promise<any> {
        const url = `${this.materialUrl}/${id}`;
        return this.http.get(url)
            .toPromise()
            .catch(this.handleError);
    }

    getForPedido(): Promise<any> {
        return this.http.get(this.materialUrl + '/forPedido' )
            .toPromise()
            .catch(this.handleError);
    }
    private handleError(error: any): Promise<any> {
        return Promise.reject(error.error || error.message || error);
    }

    getFromRubro(rubros: any): Promise<any> {
        let param = new URLSearchParams();
            param.set('rubros', rubros);
        return this.http.get(this.materialUrl + '/ofRubro?' + param.toString(), { headers: this.headers })
            .toPromise()
            .catch(this.handleError);
    }

    getLastOrdered(): Promise<any> {
        return this.http.get(this.materialUrl + '/lastOrdered', { headers: this.headers })
        .toPromise()
        .catch(this.handleError);
    }

    getFiltered(paramsIn): Promise<any> {
        const filterUrl = this.materialUrl + '/filtered?';
        let params = new URLSearchParams();
        for (let key in paramsIn) {
            params.set(key, paramsIn[key]);
        }

        return this.http.get(filterUrl + params.toString())
            .toPromise()
            .catch(this.handleError);
    }
    edit(material): Promise<any> {
        const url = this.materialUrl + '/update';
        return this.http.post(url, material)
            .toPromise()
            .catch(this.handleError);
    }
    delete(material): Promise<any> {
        const url = this.materialUrl + '/delete';
        return this.http.post(url, material)
            .toPromise()
            .catch(this.handleError);
    }
    create(material): Promise<any> {
        return this.http
            .post(this.materialUrl, material, { headers: this.headers })
            .toPromise()
            .then((resp: any) => resp.id)
            .catch(this.handleError);
    }
}



