import { Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';

import 'rxjs/add/operator/toPromise';

import { HttpHeaders } from '@angular/common/http';

@Injectable()
export class EmpleadoService {
    private empleadoUrl = 'api/empleado';
    constructor(private http: HttpClient) { }

    getAll(paramsIn): Promise<any> {
        let params = new URLSearchParams();
        for (let key in paramsIn) {
            params.set(key, paramsIn[key]);
        }

        return this.http.get(this.empleadoUrl + '?' + params.toString())
            .toPromise()
            .catch(this.handleError);
    }

    get(id: string): Promise<any> {
        const url = `${this.empleadoUrl}/${id}`;
        return this.http.get(url)
            .toPromise()
            .catch(this.handleError);
    }

    private handleError(error: any): Promise<any> {
        return Promise.reject(error.error || error.message || error);
    }
}



