import { FormGroup } from '@angular/forms';
import { Injectable } from '@angular/core';

@Injectable()
export class Global {
    selectedItemsLabel = '{0} seleccionados';

    calendarES = {
        firstDayOfWeek: 1,
        dayNames: ['domingo', 'lunes', 'martes', 'miércoles', 'jueves', 'viernes', 'sábado'],
        dayNamesShort: ['dom', 'lun', 'mar', 'mié', 'jue', 'vie', 'sáb'],
        dayNamesMin: ['D', 'L', 'M', 'X', 'J', 'V', 'S'],
        monthNames: ['enero', 'febrero', 'marzo', 'abril', 'mayo', 'junio', 'julio', 'agosto', 'septiembre', 'octubre', 'noviembre', 'diciembre'],
        monthNamesShort: ['ene', 'feb', 'mar', 'abr', 'may', 'jun', 'jul', 'ago', 'sep', 'oct', 'nov', 'dic'],
        today: 'Hoy',
        clear: 'Borrar'
    };

    getYearRange() {
        return '2017:' + (new Date().getUTCFullYear() + 5);
    }

    onlyNumbers(fc) {
        fc.patchValue(String(fc.value).replace(/[^0-9]+/g, ''));
    }

    markAsDirty(fc) {
        fc.markAsDirty();

        if (fc.controls)
            (<any>Object.keys(fc.controls).map(e => fc.controls[e])).forEach(control => {
                this.markAsDirty(control);
            });
    }

    markAsDisabled(fc) {
        fc.disable();

        if (fc.controls)
            (<any>Object.keys(fc.controls).map(e => fc.controls[e])).forEach(control => {
                this.markAsDisabled(control);
            });
    }
}



