import { Component, OnInit } from '@angular/core';
import { ActivatedRoute, ParamMap, Router } from '@angular/router';
import { Location } from '@angular/common';
import { JwtHelper } from 'angular2-jwt/angular2-jwt';

@Component({
  selector: 'app-login',
  template: '',
  providers: [JwtHelper]
})
export class LoginComponent implements OnInit {

  constructor(private router: Router, private route: ActivatedRoute, private location: Location, private jwtHelper: JwtHelper) { }

  ngOnInit(): void {
    this.route.paramMap.subscribe(params => {
      localStorage.setItem('currentUser', JSON.stringify(this.jwtHelper.decodeToken(params.get('token'))));
//      localStorage.setItem('currentUserToken', 'Authorization ' + params.get('token'));
    });
    this.router.navigate(['/']);
  }

}




