import { BrowserModule } from '@angular/platform-browser';
import { BrowserAnimationsModule } from '@angular/platform-browser/animations';
import { NgModule, LOCALE_ID } from '@angular/core';
import { CheckboxModule, } from 'primeng/primeng';
import { FormsModule, ReactiveFormsModule } from '@angular/forms';
import { HTTP_INTERCEPTORS, HttpClientModule } from '@angular/common/http';
import { AppRoutingModule } from './app-routing.module';
import { AppPrimeNGModule } from './app-primeng.module';
import { CurrencyMaskModule } from 'ng2-currency-mask';

import { AppComponent } from './components/template/app.component';
import { LoginComponent } from './components/login/login.component';
import { PedidoListadoComponent } from './components/pedido/listado.component';
import { PedidoDetalleComponent } from './components/pedido/detalle.component';
import { ProcesarListadoComponent } from './components/procesar/listado.component';
import { UsuarioCCListadoComponent } from './components/usuariocc/listado.component';
import { MaterialListadoComponent } from './components/material/listado.component';
import { StockMaterialListadoComponent } from './components/stockmaterial/listado.component';
import { RubroListadoComponent } from './components/rubro/listado.component';
import { TipoMaterialListadoComponent } from './components/tipomaterial/listado.component';
import { PrioridadListadoComponent } from './components/prioridad/listado.component';
import { JustificacionListadoComponent } from './components/justificacion/listado.component';
import { PermisosListadoComponent } from './components/permisos/listado.component';
import { AlertaListadoComponent } from './components/alerta/alerta.listado.component';
import { AlertaDetalleComponent } from './components/alerta/alerta.detalle.component';

import { AddHeaderInterceptor } from './add-header-interceptor';
import { MessageService } from 'primeng/components/common/messageservice';
import { EmpleadoService } from './service/empleado.service';
import { PedidoService } from './service/pedido.service';
import { ProcesarService } from './service/procesar.service';
import { MaterialService } from './service/material.service';
import { StockMaterialService } from './service/stockmaterial.service';
import { FavoritoService } from './service/favorito.service';
import { EstadoService } from './service/estado.service';
import { PrioridadService } from './service/prioridad.service';
import { PedidoDetalleService } from './service/pedidodetalle.service';
import { CentroCostosService } from './service/centrocostos.service';
import { UsuarioCCService } from './service/usuariocc.service';
import { ZonaService } from './service/zona.service';
import { RubroService } from './service/rubro.service';
import { TipoMaterialService } from './service/tipomaterial.service';
import { TipoAlertaService } from './service/tipoalerta.service';
import { ConfirmationService } from 'primeng/primeng';

import { JustificacionService } from './service/justificacion.service';
import { FuncionService } from './service/funcion.service';
import { PermisoService } from './service/permiso.service';
import { AlertaService } from './service/alerta.service';
import { DatePipe } from '@angular/common';
import { NumberFormatPipe } from './pipes/number-format-pipe';
import { AddSeparatorPipe } from './pipes/add-separator-pipe';
import { Global } from './global';
import { CurrencyMaskConfig, CURRENCY_MASK_CONFIG } from 'ng2-currency-mask/src/currency-mask.config';
import { CustomCurrencyMaskConfig } from './currency-mask-config';

@NgModule({
  imports: [
    BrowserModule,
    BrowserAnimationsModule,
    FormsModule,
    ReactiveFormsModule,
    HttpClientModule,
    AppRoutingModule,
    AppPrimeNGModule,
    CurrencyMaskModule,
    CheckboxModule,
  ],
  declarations: [
    AppComponent,
    LoginComponent,
    PedidoListadoComponent,
    PedidoDetalleComponent,
    ProcesarListadoComponent,
    UsuarioCCListadoComponent,
    MaterialListadoComponent,
    StockMaterialListadoComponent,
    TipoMaterialListadoComponent,
    RubroListadoComponent,
    PrioridadListadoComponent,
    JustificacionListadoComponent,
    PermisosListadoComponent,
    AlertaListadoComponent,
    AlertaDetalleComponent,
    NumberFormatPipe,
    AddSeparatorPipe
  ],
  providers: [
    { provide: LOCALE_ID, useValue: 'es-AR' },
    {
      provide: HTTP_INTERCEPTORS,

      useClass: AddHeaderInterceptor,
      multi: true,
    },
    MessageService,
    ConfirmationService,
    EmpleadoService,
    PedidoService,
    PedidoDetalleService,
    ProcesarService,
    MaterialService,
    StockMaterialService,
    FavoritoService,
    EstadoService,
    PrioridadService,
    CentroCostosService,
    UsuarioCCService,
    ZonaService,
    RubroService,
    TipoMaterialService,
    TipoAlertaService,
    JustificacionService,
    FuncionService,
    PermisoService,
    AlertaService,
    DatePipe,
    Global,
    {
      provide: CURRENCY_MASK_CONFIG,
      useValue: CustomCurrencyMaskConfig
    }
  ],
  bootstrap: [AppComponent]
})
export class AppModule { }



