import { Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';

import 'rxjs/add/operator/toPromise';

import { HttpHeaders } from '@angular/common/http';

@Injectable()
export class PedidoService {
    private pedidoUrl = 'api/pedido';
    constructor(private http: HttpClient) { }

    getAll(paramsIn): Promise<any> {
        let params = new URLSearchParams();
        for (let key in paramsIn) {
            params.set(key, paramsIn[key]);
        }

        return this.http.get(this.pedidoUrl + '?' + params.toString())
            .toPromise()
            .catch(this.handleError);
    }
    getPendiente(paramsIn): Promise<any> {
        let params = new URLSearchParams();
        for (let key in paramsIn) {
            params.set(key, paramsIn[key]);
        }

        return this.http.get(this.pedidoUrl + '/pendiente?' + params.toString())
            .toPromise()
            .catch(this.handleError);
    }

    getResuelto(paramsIn): Promise<any> {
        let params = new URLSearchParams();
        for (let key in paramsIn) {
            params.set(key, paramsIn[key]);
        }

        return this.http.get(this.pedidoUrl + '/resuelto?' + params.toString())
            .toPromise()
            .catch(this.handleError);
    }

    getTratado(paramsIn): Promise<any> {
        let params = new URLSearchParams();
        for (let key in paramsIn) {
            params.set(key, paramsIn[key]);
        }

        return this.http.get(this.pedidoUrl + '/tratado?' + params.toString())
            .toPromise()
            .catch(this.handleError);
    }

    get(id: string): Promise<any> {
        const url = `${this.pedidoUrl}/${id}`;
        return this.http.get(url)
            .toPromise()
            .catch(this.handleError);
    }

    delete(id: string): Promise<any> {
        const url = this.pedidoUrl + '/delete';
        return this.http.post(url, id)
            .toPromise()
            .catch(this.handleError);
    }

    edit(pedido): Promise<any> {
        const url = this.pedidoUrl + '/update';
        return this.http.post(url, pedido)
            .toPromise()
            .catch(this.handleError);
    }
    
    recibir(pedidos): Promise<any> {
        const url = this.pedidoUrl + '/recibir';
        return this.http.post(url, pedidos )
            .toPromise()
            .catch(this.handleError);
    }

    tratarPendientes(pedidos): Promise<any> {
        const url = this.pedidoUrl + '/tratar';
        return this.http.post(url, pedidos)
            .toPromise()
            .catch(this.handleError);
    }

    private handleError(error: any): Promise<any> {
        return Promise.reject(error.error || error.message || error);
    }
}



