import { Pipe, PipeTransform } from '@angular/core';

@Pipe({
    name: 'addSeparator'
})
export class AddSeparatorPipe implements PipeTransform {

    transform(val: string | number, separator: string, every: number ): string {
        if (val !== undefined && val !== null) {
            return this.setSeparator(val.toString(), separator, every);
        } else {
            return '';
        }
    }
    setSeparator(val, separator, every) {
        let formated = '';
        let len = val.length;
        let i = 1;
        formated += val.charAt(0);
        while ( i < len ) {
            if ( (len - i) % every === 0 ) formated += separator;
        formated += val.charAt(i);
        i++;
        }

        return formated;
    }
}



