import { SelectItem } from 'primeng/primeng';
import { Component, OnInit, ElementRef, ViewChild } from '@angular/core';
import { Router } from '@angular/router';
import { DatePipe } from '@angular/common';

import { MessageService } from 'primeng/components/common/messageservice';
import { TipoMaterialService } from './../../service/tipomaterial.service';

import { Global } from '../../global';

@Component({
    selector: 'app-tipomaterial-listado',
    templateUrl: './listado.component.html'
})
export class TipoMaterialListadoComponent implements OnInit {
    loading: boolean;
    displayDialogDelete: boolean;
    displayDialogCreate: boolean;
    displayDialogEdit: boolean;
    params;
    searchedParams;
    tipoMaterialForDelete;
    tiposMaterial = [];
    tipoMaterialForEdit;
    tipoMaterialOptions: SelectItem[] = [];

    constructor(
        private router: Router,
        private datepipe: DatePipe,
        private messageService: MessageService,
        private global: Global,
        private tipoMaterialService: TipoMaterialService) { }

    ngOnInit(): void {
        this.params = {};
        this.loadTable();
        this.setFilterTipoMat();
    }
    setFilterTipoMat() {
        this.tipoMaterialOptions = [];
        this.tipoMaterialService.getAll().then(resp => {
            resp.forEach(element => this.tipoMaterialOptions.push({ label: element['descripcion'], value: element['id'] }));
        }).catch(error => this.handleError(error));
    }
    loadTable(event?) {
        if (event) {
            this.params = event;
            this.params.filters = null;
        }

        Object.keys(this.params).forEach(key => !this.params[key] && delete this.params[key]);
        this.searchedParams = JSON.parse(JSON.stringify(this.params));
        setTimeout(() => {
            this.loading = true;
            this.tipoMaterialService.getFiltered(this.params).then(resp => {
                this.tiposMaterial = resp;
                this.loading = false;
            })
            .catch(error => { this.handleError(error);
            this.loading = false;
            });
        });
        }

    showDeleteTipoMaterial(tipoMaterial) {
        this.tipoMaterialForDelete = tipoMaterial;
        this.displayDialogDelete = true;
    }
    deleteTipoMaterial() {
        this.loading = true;
        this.tipoMaterialService.delete(this.tipoMaterialForDelete).then(id => {
            this.messageService.add({
                severity: 'success',
                detail: 'TipoMaterial borrado con \u00e9xito'
            });
            this.displayDialogDelete = false;
            this.loadTable();
            this.setFilterTipoMat();
            // this.onSubmit.emit(id);
            // this.visibleChange.emit(false);
        }).catch(error => this.handleError(error));
    }
    showEditTipoMaterial(tipoMaterial) {
        this.tipoMaterialForEdit = {
            id: tipoMaterial.id,
            descripcion: tipoMaterial.descripcion
        };
        this.displayDialogEdit = true;
    }
    editTipoMaterial() {
        if (!this.tipoMaterialForEdit['descripcion'] || this.tipoMaterialForEdit['descripcion'].trim() === '') {
            this.messageService.add({
                severity: 'error',
                detail: 'Debe ingresar el tipoMaterial'
            });
        } else {
        this.loading = true;
        this.tipoMaterialService.edit(this.tipoMaterialForEdit).then(id => {
            this.messageService.add({
                severity: 'success',
                detail: 'TipoMaterial editado con \u00e9xito'
            });
            this.loadTable();
            this.setFilterTipoMat();
            this.displayDialogEdit = false;
            // this.onSubmit.emit(id);
            // this.visibleChange.emit(false);
        }).catch(error => this.handleError(error));
        }
    }
    showCreate() {
        setTimeout(() => {
            if (this.params['newDesc']) delete this.params['newDesc'];
        });
        this.displayDialogCreate = true;
    }
    confirmTipoMaterial() {
        if (!this.params['newDesc'] || this.params['newDesc'].trim() === '') {
            this.messageService.add({
                severity: 'error',
                detail: 'Debe ingresar el tipoMaterial'
            });
        } else {
        let tipoMaterial = {
            id: null,
            descripcion: this.params['newDesc']
          };
          this.tipoMaterialService.create(tipoMaterial).then(id => {
                this.messageService.add({
                    severity: 'success',
                    detail: 'Alta exitosa'
                });
                this.loadTable();
                this.setFilterTipoMat();
                this.displayDialogCreate = false;
                delete this.params['newDesc'];
            }
          ).catch(error => this.handleError(error));
        }
    }
    handleError(error) {
        console.log(error);
        this.loading = false;
        if (error.id == 403)
            this.messageService.add({severity: 'error', detail: 'No tiene permisos para realizar la acci&oacute;n'});
        else
            this.messageService.add({severity: 'error', detail: 'Se ha producido un error'});
    }
    clearFilters() {
        this.params = {};
    }
    exportXLS() {
        let params = new URLSearchParams();
        for (let key in this.searchedParams) {
            params.set(key, this.searchedParams[key]);
        }
            window.open('api/tipoMaterial/exportXLS?' + params.toString() , '_self');
    }
}



