import { JustificacionService } from './../../service/justificacion.service';
import { SelectItem } from 'primeng/primeng';
import { Component, OnInit, ElementRef, ViewChild } from '@angular/core';
import { Router } from '@angular/router';
import { DatePipe } from '@angular/common';

import { MessageService } from 'primeng/components/common/messageservice';
import { PedidoService } from './../../service/pedido.service';
import { ZonaService } from './../../service/zona.service';
import { RubroService } from './../../service/rubro.service';
import { EstadoService } from './../../service/estado.service';
import { Global } from '../../global';
import { ProcesarService } from './../../service/procesar.service';

@Component({
    selector: 'app-procesar-listado',
    templateUrl: './listado.component.html'
})
export class ProcesarListadoComponent implements OnInit {
    loading: boolean;
    params;
    pedido = [];
    selectedpedido = [];
    zonaOptions: SelectItem[] = [];
    rubroOptions: SelectItem[] = [];
    estadoOptions: SelectItem[] = [];
    checkOk: Boolean = false;
    pedidosJustificacion = [];
    displayDialog: Boolean = false;
    justifOptions: SelectItem[] = [];
    oldFilesOptions: SelectItem[] = [];
    oldFiles: Boolean = false;

    constructor(
        private router: Router,
        private datepipe: DatePipe,
        private messageService: MessageService,
        private global: Global,
        private pedidoService: PedidoService,
        private zonaService: ZonaService,
        private rubroService: RubroService,
        private estadoService: EstadoService,
        private procesarService: ProcesarService,
        private justificacionService: JustificacionService) { }

    ngOnInit(): void {
        this.params = {};
        this.setCombos();
        this.loadTable();
    }

    setCombos() {
        this.rubroService.getAll().then(rubro => this.setSelectOptions(rubro, this.rubroOptions, 'descripcion', 'id'));
        this.zonaService.getAll().then(zona => this.setSelectOptions(zona, this.zonaOptions, 'descripcion', 'id'));
        this.estadoService.getProcessStatus().then(estados => this.setSelectOptions(estados, this.estadoOptions, 'descripcion', 'id'));
        this.justificacionService.getAll().then(justif => this.setSelectOptions(justif, this.justifOptions, 'descripcion', 'id'));
    }

    setSelectOptions(array, select, label, value) {
        array.forEach(element => {
            select.push({ label: element[label], value: element[value] });
        });
    }

    loadTable(event?) {
        if (event) {
            this.params = event;
            this.params.filters = null;
        }

        Object.keys(this.params).forEach(key => !this.params[key] && delete this.params[key]);

        setTimeout(() => {
            this.loading = true;
            this.procesarService.getAProcesar().then(resp => {
                this.pedido = resp;
                this.loading = false;
            })
            .catch(error => {
                console.log(error);
                this.loading = false;
                this.messageService.add({ severity: 'error', detail: 'Error al obtener lista de pedidos a procesar' });
            });
        });
    }

    showCantidadAprobada(row,selectedpedido){

        if ((selectedpedido.indexOf(row) != -1) && (row.estado.id == 3)) {
            row.cant_aprobada = row.cantidad;
            return true;
        } else {
            row.cant_aprobada = 0;
            return false;
        }
    }

    procesar() {
        this.selectedpedido.forEach(element => {
                                    // 4 === Rechazado.
            if ( element.estado.id === 4) {
              let id = null;
              if (element.id != null)
                id = element.id;
              let pedido = {
                id: id,
                prioridad: element.prioridad,
                estado: element.estado,
                cantidad: element.cantidad,
                material: element.material,
                validacion: element.validacion,
                observaciones: [{operacion: 'RECHAZO'}].concat(element.observaciones)
              };
              this.pedidosJustificacion.push(pedido);
/*               this.displayDialog = true; */ /* se quita justificacion a pedido del usuario */
            } else {
                if (element.cantidad !== element.cant_aprobada) {
                    let id = null;
                if (element.id != null)
                    id = element.id;
                let pedido = {
                    id: id,
                    prioridad: element.prioridad,
                    estado: element.estado,
                    cantidad: element.cantidad,
                    material: element.material,
                    validacion: element.validacion,
                    observaciones: [{operacion: 'APROBACION'}].concat(element.observaciones)
                };
                this.pedidosJustificacion.push(pedido);
   /*              this.displayDialog = true; */ /* se quita justificacion a pedido del usuario */
                }
            }
          });
          if (!this.displayDialog) {
            this.confirmProcesar();
          }
    }

    cancelDialog() {
        this.pedidosJustificacion = [];
        this.displayDialog = false;
    }

    confirmProcesar() {
        this.displayDialog = false;
        let pedidos = this.selectedpedido.filter( p => p.estado.id !== 4);
        if (this.pedidosJustificacion.length > 0) {
            pedidos = pedidos.concat(this.pedidosJustificacion);
        }
        this.pedidoService.tratarPendientes(pedidos).then(id => {
            this.messageService.add({
                severity: 'success',
                detail: 'Pedidos procesados con \u00e9xito'
            });

            this.selectedpedido = [];
            this.loadTable();
        }).catch(error => this.handleError(error));
    }

    handleError(error) {
        console.log(error);
        this.loading = false;
        if (error.id === 403)
            this.messageService.add({severity: 'error', detail: 'No tiene permisos para realizar la acci&oacute;n'});
        else
            this.messageService.add({severity: 'error', detail: 'Se ha producido un error'});
    }

    setEstadoDescripcion(event: any) {
        let ed = this.estadoOptions.find(e => e.value === event);
        if (ed) {
            return ed.label;
        }
        return  ;
    }

    clearFilters() {
        this.params = {};
        this.oldFiles = false;
        this.checkOk = false;
    }

    generarTratamiento() {
        if (this.params['zona'] && this.params['rubro']) {
            if (this.oldFiles && !this.params['numArch'])
                this.messageService.add({ severity: 'error', detail: 'Seleccione el archivo antiguo.'});
            else {
                let urlParams = new URLSearchParams();
                for (let key in this.params) {
                    urlParams.set(key, this.params[key]);
                }
                window.open('api/procesar/generarArchivo?' + urlParams.toString(), '_self');
            }
        } else {
            this.messageService.add({ severity: 'error', detail: 'Debe ingresar obligatoriamente una zona y un rubro para realizar el tratamiento.'});
        }
    }

    setOldFiles() {
        delete this.params['numArch'];
        this.clearOldFiles();
        if (this.enableFiles())
            this.procesarService.getOldFiles(this.params['rubro'], this.params['zona']).then( resp => {
                this.setSelectOptions(resp, this.oldFilesOptions, 'name', 'sec');
            })
            .catch(error => {
                if (error.message === 'ZONA_NO_CC') {
                    this.messageService.add({
                        severity: 'error', detail: 'La zona seleccionada no posee centros de costos'
                    });
                    this.clearOldFiles();
                } else
                    this.handleError(error);
            });
    }

    clearOldFiles() {
        this.oldFilesOptions = [];
    }

    enableFiles() {
        return this.oldFiles && this.params['rubro'] && this.params['zona'];
    }

    exists(data) {
        let obs = data.observaciones.find(e => e.operacion === 'JUSTIFICACION');
        if (obs !== undefined && obs.id_justificacion) {
            // reordeno el array para que la que yo busco aparezca en la pos [0]
            data.observaciones = [obs].concat(data.observaciones.filter(e => e.operacion !== 'JUSTIFICACION'));
            return true;
        }
        return false;
    }
}



