import { NgModule } from '@angular/core';

import {
    AccordionModule,
    ButtonModule,
    CalendarModule,
    DataTableModule,
    DialogModule,
    DropdownModule,
    GrowlModule,
    InputMaskModule,
    InputSwitchModule,
    InputTextModule,
    InputTextareaModule,
    MultiSelectModule,
    SharedModule,
    PanelModule,
    RadioButtonModule,
    TabViewModule,
    PickListModule,
    SpinnerModule,
    FieldsetModule,
    TooltipModule
} from 'primeng/primeng';

@NgModule({
    exports: [
        AccordionModule,
        ButtonModule,
        CalendarModule,
        DataTableModule,
        DialogModule,
        DropdownModule,
        GrowlModule,
        InputMaskModule,
        InputSwitchModule,
        InputTextModule,
        InputTextareaModule,
        MultiSelectModule,
        SharedModule,
        PanelModule,
        TabViewModule,
        SpinnerModule,
        PickListModule,
        FieldsetModule,
        TooltipModule,
        RadioButtonModule
    ]
})
export class AppPrimeNGModule { }



