import { PedidoService } from './../../service/pedido.service';
import { Component, OnInit } from '@angular/core';
import { Location } from '@angular/common';
import { Router, ActivatedRoute, Params } from '@angular/router';
import { MessageService } from 'primeng/components/common/messageservice';
import { MaterialService } from './../../service/material.service';
import { SelectItem } from 'primeng/primeng';
import { PrioridadService } from './../../service/prioridad.service';
import { Global } from '../../global';
import {
  FormGroup,
  FormControl,
  Validators,
  FormBuilder,
  FormArray
} from '@angular/forms';

import { PedidoDetalleService } from './../../service/pedidodetalle.service';
import { FavoritoService } from '../../service/favorito.service';
import { JustificacionService } from './../../service/justificacion.service';

@Component({
  selector: 'app-pedido-detalle',
  templateUrl: './detalle.component.html'
})
export class PedidoDetalleComponent implements OnInit {
  materialesParaPedidos = [];
  params;
  toRemove;
  toAdd;
  materialTable = [];
  favoritos = [];
  lastOrdered = [];
  pedidosExcedidos = [];
  materialOptions: SelectItem[] = [];
  prioridadOptions: SelectItem[] = [];
  prioridadDefault: string = '1'; /* SE PONE PRIORIDAD "NORMAL" POR DEFAULT, EN CASO DE AGREGAR MAS PRIORIDADES QUITAR ESTO */
  pedidoForm: FormGroup;
  displayDialog: boolean;
  today = new Date();
  showSelected = true;
  mostrarFav: boolean;
  showLast: boolean;
  justificacionesOptions: SelectItem[] = [];
  searchText: String = '';



  get pedidos(): FormControl {
    return this.pedidoForm.get('pedidos') as FormControl;
  }
  get pedidosLista(): FormArray {
    return this.pedidoForm.get('pedidosLista') as FormArray;
  }

  get materialesFiltered() {
    let tofilter = this.materialesParaPedidos.filter(mat => mat.material.descripcion.toUpperCase().search(this.searchText.toUpperCase()) !== -1);
    if (this.mostrarFav) {
      return tofilter.filter(m => this.favoritos.find(f => f.material.id === m.material.id ));
    }
    if (this.showLast) return tofilter.filter(m => this.lastOrdered.find(l => l.id === m.material.id));
    return tofilter;
  }

  constructor(
    private route: ActivatedRoute,
    private router: Router,
    private global: Global,
    private messageService: MessageService,
    private materialService: MaterialService,
    private favoritoService: FavoritoService,
    private pedidoDetalleService: PedidoDetalleService,
    private prioridadService: PrioridadService,
    private justificacionService: JustificacionService,
    private fb: FormBuilder
  ) { }

  ngOnInit() {

    this.setForm();
    this.params = {};

    this.materialService.getForPedido().then(material => {
      this.materialTable = material;
      this.materialTable.forEach(element => {
        this.materialesParaPedidos.push({
          material: element,
          show: false,
          prioridad: { id: null, descripcion: null }
        });
      });
    });

    this.favoritoService.getAll().then(favoritos => {
      this.favoritos = favoritos;
    });

    this.materialService.getLastOrdered().then(resp => {
      this.lastOrdered = resp;
    });

    this.prioridadService
      .getAll()
      .then(prioridad =>
        this.setSelectOptions(
          prioridad,
          this.prioridadOptions,
          'descripcion',
          'id'
        )
      );
    this.pedidoForm = this.fb.group({
      pedidosLista: new FormArray([])
    });
    this.route.params.subscribe((params: Params) => { });
    this.justificacionService.getAll().then(justificacion => this.setSelectOptions(justificacion, this.justificacionesOptions, 'descripcion', 'id'));
  }

  goBack() {
    this.router.navigate(['/pedidos']);
  }
  setSelectOptions(array, select, label, value) {
    array.forEach(element => {
      select.push({ label: element[label], value: element[value] });
    });
  }
  submit() {
    if (this.pedidosLista.length == 0) {
      this.messageService.add({
        severity: 'error',
        detail: 'El pedido debe poseer al menos un material.'
        });
    } else {
/*       if (!this.isValid()) {
        this.messageService.add({
          severity: 'error',
          detail: 'Debe ingresar la prioridad de cada pedido.'
          });
        } else 
        { */
        this.pedidosLista.value.forEach(element => { // CANTIDAD MEDIA VA A SER REEMPLAZADO POR LA JUSTIFICADA, MÍNIMA DESAPARECER.
          if ( element.cantidad > element.material.cantidad_media) {
            let id = null;
            if (element.id != null)
              id = element.id;
            console.log(element);
            let pedido = {
              id: id,
              prioridad: { id: element.prioridad },
              cantidad: element.cantidad,
              material: element.material,
              justificacion: element.justificacion,
              observaciones: [{operacion: 'JUSTIFICACION'}]
            };
            console.log(pedido);
            this.pedidosExcedidos.push(pedido);
            this.displayDialog = true;
          }
        });
        if (!this.displayDialog) {
          this.confirmPedido();
        }
   /*    } */
    }
  }
/*   isValid() {
    let valid = true;
    this.pedidosLista.value.forEach(pedido => {
      if (!pedido['prioridad']) valid = false;
    });
    return valid;
  } */
  cancelDialog() {
    this.pedidosExcedidos = [];
    this.displayDialog = false;

  }
  confirmPedido() {
    this.displayDialog = false;
    let pedido: any = this.formToPedido();
    if (this.pedidosExcedidos.length > 0) {
      pedido = pedido.concat(this.pedidosExcedidos);
      console.log(JSON.stringify(pedido));
    }
    this.pedidoDetalleService
      .create(pedido)
      .then(id => {
        this.messageService.add({
          severity: 'success',
          detail: 'Pedido creado con \u00e9xito'
        });
        this.goBack();
      })
      .catch(error => this.handleError(error));
  }
  handleError(error) {
    console.log(error);
    this.messageService.add({
      severity: 'error',
      detail: 'Se ha producido un error'
    });
  }
  setForm() {
    this.pedidoForm = this.fb.group({
      pedidosLista: new FormArray([])
    });
  }

  addMaterialPedido(materialId) {
    let newPedido = this.fb.group({
      material: this.materialesParaPedidos.find(f => f.material.id === materialId).material,
      cantidad: new FormControl(1, [Validators.required, Validators.min(1)]),
      prioridad: new FormControl('', [Validators.required])
    });
    this.materialesParaPedidos.splice(this.materialesParaPedidos.indexOf(this.materialesParaPedidos
      .find(m => m.material.id === materialId)), 1);
    this.pedidosLista.push(newPedido);
    console.log('sh ' + JSON.stringify(newPedido.controls.material.value));
    console.log(newPedido.controls.material.value.tipo_material);
  }
  removeMaterialFromPedido(i) {
    console.log('addMaterialPedido1' + i);
    let newPedido = {
      material: this.pedidosLista.controls[i].value.material,
    };
    console.log(this.pedidosLista.controls[i].value.material);
    this.pedidosLista.removeAt(i);
    console.log('addMaterialPedido3' + i);
    this.materialesParaPedidos.push(newPedido);
    console.log('addMaterialPedido4' + i);
  }

  formToPedido() {
    let pedidosList = [];
    this.pedidosLista.value.forEach(element => {
      let id = null;
      if (element.id != null)
        id = element.id;
      console.log(element);
      let pedido = {
        id: id,
        prioridad: { id: element.prioridad },
        cantidad: element.cantidad,
        material: element.material
      };
      console.log(pedido);
      pedidosList.push(pedido);
    });
    console.log('pelist:');
    console.log(pedidosList);
    return pedidosList.filter(p => p.cantidad <= p.material.cantidad_media);
  }

  checkFavorito(materialId) {
    return this.favoritos.filter(f => f.material.id === materialId).length === 0;
  }

  addFavorito(materialId) {
    this.favoritoService
    .add(materialId)
    .then(id => {
      let favorito = {
        material: {
          id: materialId
        }
      };
      this.favoritos.push(favorito);
    })
    .catch(error => console.log(error));
  }

  deleteFavorito(materialId) {
    this.favoritoService
    .delete(materialId)
    .then(id => {
      this.favoritos.splice(this.favoritos.indexOf(this.favoritos.find(f => f.material.id === materialId)), 1);
    })
    .catch(error => console.log(error));
  }
}



