import { SelectItem } from 'primeng/primeng';
import { Component, OnInit, ElementRef, ViewChild } from '@angular/core';
import { Router } from '@angular/router';
import { DatePipe } from '@angular/common';

import { MessageService } from 'primeng/components/common/messageservice';
import { PrioridadService } from './../../service/prioridad.service';

import { Global } from '../../global';

@Component({
    selector: 'app-prioridad-listado',
    templateUrl: './listado.component.html'
})
export class PrioridadListadoComponent implements OnInit {
    loading: boolean;
    displayDialogDelete: boolean;
    displayDialogCreate: boolean;
    displayDialogEdit: boolean;
    params;
    searchedParams;
    prioridadForDelete;
    prioridades = [];
    prioridadForEdit;
    prioridadOptions: SelectItem[] = [];

    constructor(
        private router: Router,
        private datepipe: DatePipe,
        private messageService: MessageService,
        private global: Global,
        private prioridadService: PrioridadService) { }

    ngOnInit(): void {
        this.params = {};
        this.setFilterPrioridad();
    }
    setFilterPrioridad() {
        this.prioridadOptions = [];
        this.prioridadService.getAll().then(resp => {
            this.prioridades = resp;
            resp.forEach(element => this.prioridadOptions.push({ label: element['descripcion'], value: element['id'] }));
        }).catch(error => this.handleError(error));
    }
    loadTable(event?) {
        if (event) {
            this.params = event;
            this.params.filters = null;
        }

        Object.keys(this.params).forEach(key => !this.params[key] && delete this.params[key]);
        this.searchedParams = JSON.parse(JSON.stringify(this.params));
        setTimeout(() => {
            this.loading = true;
            this.prioridadService.getFiltered(this.params).then(resp => {
                this.prioridades = resp;
                this.loading = false;
            })
            .catch(error => { this.handleError(error);
            this.loading = false;
            });
        });
        }

    showDeletePrioridad(prioridad) {
        this.prioridadForDelete = prioridad;
        this.displayDialogDelete = true;
    }
    deletePrioridad() {
        this.loading = true;
        this.prioridadService.delete(this.prioridadForDelete).then(id => {
            this.messageService.add({
                severity: 'success',
                detail: 'Prioridad borrada con \u00e9xito'
            });
            this.displayDialogDelete = false;
            this.loadTable();
            this.setFilterPrioridad();
            // this.onSubmit.emit(id);
            // this.visibleChange.emit(false);
        }).catch(error => this.handleError(error));
    }
    showEditPrioridad(prioridad) {
        this.prioridadForEdit = {
            id: prioridad.id,
            descripcion: prioridad.descripcion
        };
        this.displayDialogEdit = true;
    }
    editPrioridad() {
        if (!this.prioridadForEdit['descripcion'] || this.prioridadForEdit['descripcion'].trim() === '' ) {
            this.messageService.add({
                severity: 'error',
                detail: 'Debe ingresar la prioridad'
            });
        }else {
        this.loading = true;
        this.prioridadService.edit(this.prioridadForEdit).then(id => {
            this.messageService.add({
                severity: 'success',
                detail: 'Prioridad editada con \u00e9xito'
            });
            this.loadTable();
            this.setFilterPrioridad();
            this.displayDialogEdit = false;
            // this.onSubmit.emit(id);
            // this.visibleChange.emit(false);
        }).catch(error => this.handleError(error));
        }
    }
    showCreate() {
        setTimeout(() => {
            if (this.params['newDesc']) delete this.params['newDesc'];
        });
        this.displayDialogCreate = true;
    }
    confirmPrioridad() {
        if (!this.params['newDesc'] || this.params['newDesc'].trim()  === '') {
            this.messageService.add({
                severity: 'error',
                detail: 'Debe ingresar la prioridad'
            });
        } else {
        let prioridad = {
            id: null,
            descripcion: this.params['newDesc']
          };
          this.prioridadService.create(prioridad).then(id => {
                this.messageService.add({
                    severity: 'success',
                    detail: 'Alta exitosa'
                });
                this.loadTable();
                this.setFilterPrioridad();
                this.displayDialogCreate = false;
                delete this.params['newDesc'];
            }
          ).catch(error => this.handleError(error));
        }
    }
    handleError(error) {
        console.log(error);
        this.loading = false;
        if (error.id == 403)
            this.messageService.add({severity: 'error', detail: 'No tiene permisos para realizar la acci&oacute;n'});
        else
            this.messageService.add({severity: 'error', detail: 'Se ha producido un error'});
    }
    clearFilters() {
        this.params = {};
    }
    exportXLS() {
        let params = new URLSearchParams();
        for (let key in this.searchedParams) {
            params.set(key, this.searchedParams[key]);
        }
            window.open('api/prioridad/exportXLS?' + params.toString() , '_self');
    }
}



