import { SelectItem, ConfirmationService } from 'primeng/primeng';
import { Component, OnInit, ElementRef, ViewChild } from '@angular/core';
import { Router } from '@angular/router';
import { DatePipe } from '@angular/common';

import { MessageService } from 'primeng/components/common/messageservice';
import { Global } from '../../global';
import { AlertaService } from '../../service/alerta.service';
import { MaterialService } from './../../service/material.service';
import { CentroCostosService } from './../../service/centrocostos.service';
import { TipoAlertaService } from './../../service/tipoalerta.service';
import { THIS_EXPR } from '@angular/compiler/src/output/output_ast';

@Component({
    selector: 'app-alerta-listado',
    templateUrl: './alerta.listado.component.html'
})
export class AlertaListadoComponent implements OnInit {
    loading: boolean;
    params;
    alerta;
    alertas = [];
    materiales = [];
    centrosCosto = [];
    tipoAlertas = [];
    showDialogAlerta = false;
    actionDialog;
    materialOptions: SelectItem[] = [];
    centroCostosOptions: SelectItem[] = [];
    tipoAlertaOptions: SelectItem[] = [];

    constructor(
        private router: Router,
        private global: Global,
        private messageService: MessageService,
        private materialService: MaterialService,
        private centroCostosService: CentroCostosService,
        private tipoAlertaService: TipoAlertaService,
        private confirmationService: ConfirmationService,
        private alertaService: AlertaService) { }

    ngOnInit(): void {
        this.params = {};
        this.setCombos();
    }

    setCombos() {
        this.materialService.getAll().then(material => {
            this.materiales = material;
            this.setSelectOptions(material, this.materialOptions, 'descripcion', 'id');
        });
        this.centroCostosService.getAll().then(centroCostos => {
            this.centrosCosto = centroCostos;
            this.setSelectOptions(centroCostos, this.centroCostosOptions, 'descripcion', 'id')
        });
        this.tipoAlertaService.getAll()
            .then(resp => {
                this.tipoAlertas = resp;
                this.tipoAlertas.forEach(ta => this.tipoAlertaOptions.push({
                    label: ta.tipoAlerta.descripcion + ' ' + ta.periodo.descripcion,
                    value: ta.tipoAlerta.id + '_' + ta.periodo.id
                }));
            });
    }

    setSelectOptions(array, select, label, value) {
        array.forEach(element => {
            select.push({ label: element[label], value: element[value] });
        });
    }

    loadTable(event) {
        if (event) {
            this.params.filters = null;
        }

        Object.keys(this.params).forEach(key => !this.params[key] && delete this.params[key]);

        setTimeout(() => {
            this.loading = true;
            this.alertaService.getAll(this.params).then(resp => {
                this.alertas = resp;
                this.loading = false;
            })
            .catch(error => {
                console.log(error);
                this.loading = false;
                this.messageService.add({ severity: 'error', detail: 'Error al obtener lista de alertas' });
            });
        });
    }

    clearFilters() {
        this.params = {

        };
    }

    create() {
        this.actionDialog = 'new';
        this.alerta = null;
        this.showDialogAlerta = true;
    }

    edit(alerta) {
        this.actionDialog = 'edit';
        this.alerta = alerta;
        this.showDialogAlerta = true;
    }

    delete(alerta) {
        this.confirmationService.confirm({
            message: '&iquest;Desea eliminar la alerta?<br>' +
                'Material: ' + alerta.material.descripcion + '<br>' +
                'Centro de Costos: ' + alerta.centroCostos.id + ' - ' + alerta.centroCostos.descripcion + '<br>' +
                'Tipo de Alerta: ' + alerta.tipoAlerta.descripcion + ' ' + alerta.periodo.descripcion,
            icon: 'fa-question-circle',
            accept: () => this.confirmDelete(alerta)
        });
    }
    

    confirmDelete(alerta) {
        this.alertaService.delete(alerta.id).then(resp => {
            this.messageService.add({
                severity: 'success',
                detail: 'Alerta eliminada con \u00e9xito'
            });
            this.loadTable(null);
        })
        .catch(error => {
            console.log(error);
            this.messageService.add({
                severity: 'error',
                detail: 'Error al eliminar alerta'
            });
        });
    }

    deleteAlerta(alerta) {
        this.loading = true;
        this.alertaService.delete(alerta.id).then(resp => {
            this.messageService.add({
                severity: 'success',
                detail: 'Alerta eliminada con \u00e9xito'
            });
            this.loadTable(null);
        })
        .catch(error => {
            console.log(error);
            this.messageService.add({
                severity: 'error',
                detail: 'Error al eliminar alerta'
            });
        });
    }
    
}



