import { SelectItem, CheckboxModule } from 'primeng/primeng';
import { Component, OnInit, ElementRef, ViewChild } from '@angular/core';
import { Router } from '@angular/router';
import { DatePipe } from '@angular/common';

import { MessageService } from 'primeng/components/common/messageservice';
import { CentroCostosService } from './../../service/centrocostos.service';
import { UsuarioCCService } from './../../service/usuariocc.service';
import { Global } from '../../global';

@Component({
    selector: 'app-usercc-listado',
    templateUrl: './listado.component.html'
})
export class UsuarioCCListadoComponent implements OnInit {
    loading: boolean;
    displayDialogDelete: boolean;
    displayDialogCreate: boolean;
    params;
    userCCForDelete;
    usrcc = [];
    filteredCC = [];
    centroCostosOptions: SelectItem[] = [];

    constructor(
        private router: Router,
        private datepipe: DatePipe,
        private messageService: MessageService,
        private global: Global,
        private centroCostosService: CentroCostosService,
        private usuarioCCService: UsuarioCCService) { }

    ngOnInit(): void {
        this.params = {};
        this.loadTable();
        this.setCombos();
    }
    setCombos() {
        this.centroCostosService.getAll().then(centroCostos => this.setSelectOptions(centroCostos, this.centroCostosOptions, 'descripcion', 'id'));
    }

    setSelectOptions(array, select, label, value) {
        array.forEach(element => {
            select.push({ label: element[label], value: element[value] });
        });
    }
    loadTable(event?) {
        if (event) {
            this.params = event;
            this.params.filters = null;
        }

        Object.keys(this.params).forEach(key => !this.params[key] && delete this.params[key]);

        setTimeout(() => {
            this.loading = true;
            this.usuarioCCService.getFiltered(this.params).then(resp => {
                this.usrcc = resp;
                this.loading = false;
            })
            .catch(error => { this.handleError(error);
            this.loading = false;
            });
        });
        }

    showDeleteUserCC(userCC) {
        console.log(userCC);
        this.userCCForDelete = userCC;
        this.displayDialogDelete = true;
    }
    deleteUserCC() {
        console.log(this.userCCForDelete);
        this.loading = true;
        this.usuarioCCService.delete(this.userCCForDelete).then(id => {
            this.messageService.add({
                severity: 'success',
                detail: 'Borrado exitoso'
            });
            this.displayDialogDelete = false;
            this.loadTable();
            // this.onSubmit.emit(id);
            // this.visibleChange.emit(false);
        }).catch(error => this.handleError(error));
    }
    filterCCByUser() {
        if (!this.params['newlegajo'] || this.params['newlegajo'].length !== 7) {
            this.filteredCC = [];
            this.messageService.add({
                severity: 'error',
                detail: 'El legajo debe ser de 7 caracteres'
            });
        }else {
                let paramsUser = {
                    legajo: this.params['newlegajo'].toUpperCase()
                };
                this.usuarioCCService.getFiltered(paramsUser).then(resp => {
                    this.filteredCC = this.centroCostosOptions;
                    resp.forEach(element => this.filteredCC = this.filteredCC.filter(e => e.value !== element.centroCostos.id));
                });
            }
    }
    showCreate() {
        setTimeout(() => {
            if (this.params['newLejago']) delete this.params['newlegajo'];
            if (this.params['newcc']) delete this.params['newcc'];
        });
        this.displayDialogCreate = true;
    }
    confirmUserCC() {
        if (!this.params['newlegajo'] || this.params['newlegajo'].length !== 7) {
            this.messageService.add({
                severity: 'error',
                detail: 'El legajo debe ser de 7 caracteres'
            });
        } else if (!this.params['newcc'] || this.params['newcc'] === '') {
            this.messageService.add({
                severity: 'error',
                detail: 'Debe seleccionar un centro de costos'
            });
        } else {
            console.log(this.params['newcc']);
        let userCC = {
            legajo: this.params['newlegajo'].toUpperCase(),
            centroCostos: this.params['newcc']
          };
          this.usuarioCCService.create(userCC).then(id => {
                this.messageService.add({
                    severity: 'success',
                    detail: 'Alta exitosa'
                });
                this.displayDialogCreate = false;
                delete this.params['newlegajo'];
                delete this.params['newcc'];
                this.loadTable();
            }
          ).catch(error => this.handleError(error));
        }
    }
    handleError(error) {
        console.log(error);
        this.loading = false;
        if (error.id == 403)
            this.messageService.add({severity: 'error', detail: 'No tiene permisos para realizar la acci&oacute;n'});
        else
            this.messageService.add({severity: 'error', detail: 'Se ha producido un error'});
    }
}



